sys_variable_value.value:
(function execute(inputs, outputs) {

    var response = JSON.parse(inputs.response_body);

    outputs.qr_id = response.qr_id || "";
    outputs.qr_data = response.qr_data || "";
    outputs.qr_image_url = response.qr_image_url || "";

})(inputs, outputs);

